const numberToWords = (input: number | string): string => {
  const num = Number(input);
  if (isNaN(num)) return "Invalid input";

  const ones = [
    "",
    "One",
    "Two",
    "Three",
    "Four",
    "Five",
    "Six",
    "Seven",
    "Eight",
    "Nine",
  ];
  const teens = [
    "Ten",
    "Eleven",
    "Twelve",
    "Thirteen",
    "Fourteen",
    "Fifteen",
    "Sixteen",
    "Seventeen",
    "Eighteen",
    "Nineteen",
  ];
  const tens = [
    "",
    "",
    "Twenty",
    "Thirty",
    "Forty",
    "Fifty",
    "Sixty",
    "Seventy",
    "Eighty",
    "Ninety",
  ];

  const convertHundreds = (n: number): string => {
    let result = "";
    if (n >= 100) {
      result += ones[Math.floor(n / 100)] + " Hundred ";
      n %= 100;
    }
    if (n >= 20) {
      result += tens[Math.floor(n / 10)] + " ";
      n %= 10;
    } else if (n >= 10) {
      result += teens[n - 10] + " ";
      return result;
    }
    if (n > 0) {
      result += ones[n] + " ";
    }
    return result;
  };

  const convertNumber = (num: number): string => {
    if (num === 0) return "Zero ";

    let result = "";
    const crore = Math.floor(num / 10000000);
    const lakh = Math.floor((num % 10000000) / 100000);
    const thousand = Math.floor((num % 100000) / 1000);
    const remainder = num % 1000;

    if (crore > 0) result += convertHundreds(crore) + "Crore ";
    if (lakh > 0) result += convertHundreds(lakh) + "Lakh ";
    if (thousand > 0) result += convertHundreds(thousand) + "Thousand ";
    if (remainder > 0) result += convertHundreds(remainder);

    return result.trim() + " ";
  };

  const rupees = Math.floor(num);
  const paisa = Math.round((num - rupees) * 100);

  let result = "";
  if (rupees > 0) {
    result += convertNumber(rupees) + "Rupees";
  }
  if (paisa > 0) {
    result += (rupees > 0 ? " and " : "") + convertNumber(paisa) + "Paisa";
  }
  if (rupees === 0 && paisa === 0) {
    return "Zero Rupees Only";
  }

  return result.trim() + " Only";
};


// --- Text-rate support -------------------------------------------------
// A product rate may be a number (normal behaviour) or free text such as
// "Channel Partner Rate". Text rates are echoed into the Amount column.
const numAmount = (v: unknown): number =>
  typeof v === "number" ? v : Number(v) || 0;
const isTextValue = (v: unknown): boolean =>
  typeof v === "string" && v.trim() !== "" && isNaN(Number(v));
const textAmountsOf = (data: InvoiceData): string[] =>
  data.products.map((p) => p.amount).filter(isTextValue) as string[];
const withText = (num: number, texts: string[]): string => {
  if (texts.length === 0) return num.toFixed(2);
  const joined = texts.join(" + ");
  return num > 0 ? `${num.toFixed(2)} + ${joined}` : joined;
};
const gstWithText = (num: number, texts: string[], rate: number): string => {
  if (texts.length === 0) return num.toFixed(2);
  const joined = `${rate}% GST on ${texts.join(" + ")}`;
  return num > 0 ? `${num.toFixed(2)} + ${joined}` : joined;
};

const calculateTotals = (data: InvoiceData) => {
  const subtotal = data.products.reduce(
    (sum, product) => sum + numAmount(product.amount),
    0
  );
  const totalWithExtras = subtotal + data.freight + data.insurance + data.tcs;

  const gstRate = data.gstRate ?? 18; // Default to 18% if not specified

  const cgstAmount = data.isIgstApplicable
    ? 0
    : (totalWithExtras * (gstRate / 2)) / 100;
  const sgstAmount = data.isIgstApplicable
    ? 0
    : (totalWithExtras * (gstRate / 2)) / 100;
  const igstAmount = data.isIgstApplicable
    ? (totalWithExtras * gstRate) / 100
    : 0;

  const totalTax = cgstAmount + sgstAmount + igstAmount;
  const grandTotal = totalWithExtras + totalTax;

  return {
    textAmounts: textAmountsOf(data),
    subtotal,
    totalWithExtras,
    cgstAmount,
    sgstAmount,
    igstAmount,
    totalTax,
    grandTotal,
    gstRate,
  };
};

// Function to group products by HSN and calculate totals per HSN
const groupProductsByHSN = (data: InvoiceData) => {
  const hsnGroups: { [key: string]: { products: any[]; totalAmount: number } } =
    {};

  // Group products by HSN
  data.products.forEach((product) => {
    const hsn = product.hsn || ""; // Default HSN if not specified
    if (!hsnGroups[hsn]) {
      hsnGroups[hsn] = { products: [], totalAmount: 0 };
    }
    hsnGroups[hsn].products.push(product);
    hsnGroups[hsn].totalAmount += numAmount(product.amount);
  });

  // Convert to array and add freight/insurance proportionally
  const hsnEntries = Object.entries(hsnGroups);
  const totalProductAmount = data.products.reduce(
    (sum, product) => sum + numAmount(product.amount),
    0
  );
  const gstRate = data.gstRate ?? 18;// Default to 18% if not specified

  return hsnEntries.map(([hsn, group]) => {
    const proportion =
      totalProductAmount > 0 ? group.totalAmount / totalProductAmount : 0;
    const freightShare = data.freight * proportion;
    const insuranceShare = data.insurance * proportion;
    const tcsShare = data.tcs * proportion;

    const taxableValue =
      group.totalAmount + freightShare + insuranceShare + tcsShare;

    const cgstAmount = data.isIgstApplicable
      ? 0
      : (taxableValue * (gstRate / 2)) / 100;
    const sgstAmount = data.isIgstApplicable
      ? 0
      : (taxableValue * (gstRate / 2)) / 100;
    const igstAmount = data.isIgstApplicable
      ? (taxableValue * gstRate) / 100
      : 0;

    return {
      hsn,
      taxableValue,
      cgstAmount,
      sgstAmount,
      igstAmount,
      totalTax: cgstAmount + sgstAmount + igstAmount,
      productCount: group.products.length,
    };
  });
};

