export const generatePDF = async (data: InvoiceData) => {
  const copyTypes = [
    "Original For Buyer"
  ];

  try {
    // Generate all 4 copies in one PDF
    const allCopiesHTML = copyTypes
      .map((copyType) => generateInvoiceHTML(data, copyType))
      .join('<div style="page-break-before: always;"></div>');

    const element = document.createElement("div");
    element.innerHTML = allCopiesHTML;
    document.body.appendChild(element);

    const opt = {
      margin: [0.3, 0.3, 0.3, 0.3] as [number, number, number, number],
      filename: `PO-${
        data.invoiceNumber?.replace(/\//g, "-") || "DTS-PO-2026-27-001"
      }.pdf`,
      image: { type: "jpeg" as const, quality: 0.98 },
      html2canvas: {
        scale: 2,
        useCORS: true,
        letterRendering: true,
        allowTaint: false,
      },
      jsPDF: {
        unit: "in",
        format: "a4",
        orientation: "portrait" as const,
      },
      pagebreak: { mode: ["avoid-all", "css", "legacy"] },
    };

    await html2pdf().set(opt).from(element).save();

    // Clean up
    document.body.removeChild(element);

    console.log("PDF generated successfully");
  } catch (error) {
    console.error("Error generating PDF:", error);
    throw new Error("Failed to generate PDF");
  }
};
